let lang='fa',provider='igap',state=null,countries=[],pollBusy=false;try{lang=localStorage.getItem('providerLab.lang')||'fa';provider=localStorage.getItem('providerLab.provider')||'igap';document.documentElement.dataset.theme=localStorage.getItem('providerLab.theme')||'dark';}catch{}
