function t(name){return(messages[name]||messages.request_failed)[lang==='fa'?0:1];}
function notice(text,bad=false){$('message').textContent=text;$('message').dataset.error=String(bad);$('message').hidden=!text;}
function errorText(e){return t(e.serviceCode&&messages['eitaa_'+e.serviceCode]?'eitaa_'+e.serviceCode:e.serviceCode&&messages['rubika_'+e.serviceCode]?'rubika_'+e.serviceCode:e.serviceType&&messages['nasim_'+e.serviceType]?'nasim_'+e.serviceType:e.reason||'request_failed')+(Number.isInteger(e.major)?' · '+e.major+'/'+e.minor:'')+(e.waitSeconds?' · '+e.waitSeconds+' '+t('seconds'):'');}
async function api(route,body){const response=await fetch('/api/'+route,{method:body===undefined?'GET':'POST',headers:{Authorization:'Bearer '+key,...body===undefined?{}:{'Content-Type':'application/json'}},body:body===undefined?undefined:JSON.stringify(body)});const data=await response.json();if(!response.ok||data.ok===false)throw data;return data;}
function translate(){$('theme').setAttribute('aria-label',lang==='fa'?'پوسته':'Theme');$('providers').setAttribute('aria-label',t('providers'));for(const e of document.querySelectorAll('.help'))e.setAttribute('aria-label',lang==='fa'?'راهنما':'Help');document.documentElement.lang=lang;document.documentElement.dir=lang==='fa'?'rtl':'ltr';for(const e of document.querySelectorAll('[data-i18n]'))e.textContent=t(e.dataset.i18n);for(const e of document.querySelectorAll('[data-help]'))e.title=t(e.dataset.help);$('language').textContent=lang==='fa'?'EN':'فا';$('vaultPassword').placeholder=t('password_too_short');$('vaultPassword').setAttribute('aria-label',t('vault'));for(const card of document.querySelectorAll('.account'))card.querySelector('h3').textContent=t('account')+' '+card.dataset.slot;fillCountries();selectProvider(provider,false);render();}
function selectProvider(id,save=true){provider=id;$('eitaaPanel').hidden=id!=='eitaa';for(const button of document.querySelectorAll('#providers [data-provider]'))button.setAttribute('aria-selected',String(button.dataset.provider===id));$('providerTitle').textContent=t(id);$('igapPanel').hidden=id!=='igap';$('nasimPanel').hidden=id!=='nasim';$('rubikaPanel').hidden=id!=='rubika';$('researchPanel').hidden=['igap','nasim','rubika','eitaa'].includes(id);if(!['igap','nasim','rubika','eitaa'].includes(id)){$('researchStatus').textContent=t(id+'Detail');$('officialLink').href=({eitaa:'https://web.eitaa.com/',nasim:'https://web.nasimrezvan.com/',rubika:'https://web.rubika.ir/'})[id];}if(save)try{localStorage.setItem('providerLab.provider',id);}catch{}}
function fillCountries(){if(!countries.length)return;const names=new Intl.DisplayNames([lang],{type:'region'});for(const select of document.querySelectorAll('[data-country]')){const current=select.value||'IR';select.replaceChildren(...countries.map(c=>{const option=document.createElement('option');option.value=c.iso;option.textContent='\u2066+'+c.code+'\u2069 '+(names.of(c.iso)||c.iso);return option;}));select.value=current;select.setAttribute('aria-label',t('countryChoose'));updateFlag(select);}}
function updateFlag(select){const card=select.closest('.account'),country=countries.find(c=>c.iso===select.value);if(country){card.querySelector('.phone-control img').src='/flags/'+country.iso+'.svg';const trigger=card.querySelector('[data-country-open]');if(trigger){const name=new Intl.DisplayNames([lang],{type:'region'}).of(country.iso);trigger.textContent='+'+country.code+' '+country.iso+' ▾';trigger.title=name;trigger.setAttribute('aria-label',t('countryChoose')+': '+name+' +'+country.code);}}}

// A single local picker serves all accounts. Search never leaves the browser.
const countryPicker=document.createElement('dialog');countryPicker.className='country-picker';countryPicker.id='countryPicker';countryPicker.setAttribute('aria-labelledby','countryPickerTitle');
countryPicker.innerHTML='<div class="country-picker-heading"><strong id="countryPickerTitle"></strong><button type="button" data-country-close>×</button></div><input id="countrySearch" type="search" autocomplete="off" spellcheck="false" aria-controls="countryResults"><div id="countryResults" role="listbox"></div><p id="countryEmpty" role="status" hidden></p>';
document.body.append(countryPicker);let countryTarget=null,countryReturnFocus=null;
function countryNormalize(value){return String(value).normalize('NFKD').replace(/\p{M}/gu,'').replace(/ي/g,'ی').replace(/ك/g,'ک').replace(/[۰-۹]/g,c=>String(c.charCodeAt(0)-1776)).replace(/[٠-٩]/g,c=>String(c.charCodeAt(0)-1632)).trim().toLowerCase();}
function countryResults(){const names=new Intl.DisplayNames([lang],{type:'region'}),fa=new Intl.DisplayNames(['fa'],{type:'region'}),en=new Intl.DisplayNames(['en'],{type:'region'}),query=countryNormalize($('countrySearch').value),code=query.replace(/^\+/,'').replace(/^00/,'');const matches=countries.filter(c=>!query||countryNormalize([c.iso,fa.of(c.iso),en.of(c.iso)].join(' ')).includes(query)||/^\d+$/.test(code)&&c.code.startsWith(code));
 $('countryResults').replaceChildren(...matches.map(c=>{const button=document.createElement('button');button.type='button';button.dataset.countryResult=c.iso;button.tabIndex=-1;button.setAttribute('role','option');button.setAttribute('aria-selected',String(c.iso===countryTarget?.value));const flag=document.createElement('img');flag.src='/flags/'+c.iso+'.svg';flag.alt='';flag.loading='lazy';const name=document.createElement('span');name.textContent=names.of(c.iso);const dial=document.createElement('bdi');dial.textContent='+'+c.code;button.append(flag,name,dial);button.onclick=()=>{if(countryTarget&&!countryTarget.disabled){countryTarget.value=c.iso;countryTarget.dispatchEvent(new Event('change',{bubbles:true}));}countryPicker.close();};return button;}));$('countryEmpty').hidden=matches.length>0;
}
function openCountryPicker(select,trigger){if(select.disabled||!countries.length)return;countryTarget=select;countryReturnFocus=trigger;$('countryPickerTitle').textContent=t('countryChoose');$('countrySearch').placeholder=t('countrySearch');$('countrySearch').setAttribute('aria-label',t('countrySearch'));$('countryEmpty').textContent=t('countryEmpty');countryPicker.querySelector('[data-country-close]').setAttribute('aria-label',t('close'));$('countrySearch').value='';countryResults();trigger.setAttribute('aria-expanded','true');countryPicker.showModal();$('countrySearch').focus();}
countryPicker.querySelector('[data-country-close]').onclick=()=>countryPicker.close();
countryPicker.addEventListener('close',()=>{countryReturnFocus?.setAttribute('aria-expanded','false');countryReturnFocus?.focus();countryTarget=null;});
countryPicker.addEventListener('click',event=>{if(event.target===countryPicker){const r=countryPicker.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)countryPicker.close();}});
$('countrySearch').addEventListener('input',countryResults);
countryPicker.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();countryPicker.close();return;}const options=[...$('countryResults').querySelectorAll('button')],index=options.indexOf(document.activeElement);if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();options[index<0?(event.key==='ArrowDown'?0:options.length-1):(index+(event.key==='ArrowDown'?1:-1)+options.length)%options.length]?.focus();}else if(event.key==='Enter'&&event.target===$('countrySearch')){event.preventDefault();options[0]?.click();}else if(event.key==='Home'&&index>=0){event.preventDefault();options[0]?.focus();}else if(event.key==='End'&&index>=0){event.preventDefault();options.at(-1)?.focus();}});
function statusOf(a){if(a.busy)return'loading';if(a.provider==='eitaa'&&a.stage==='uncertain')return'eitaa_uncertain';if(a.provider==='eitaa'&&a.stage==='refresh_required')return'eitaa_refresh_required';if(a.provider==='eitaa'&&a.stage==='code'&&a.codeHashSource==='localCompatibility')return'eitaa_code_unconfirmed';if(a.signedIn)return'signed';if(a.stage==='profile_required')return'profileState';if(a.stage==='password')return a.provider!=='igap'||a.connected?'passwordState':'expired';if(a.stage==='code')return a.provider!=='igap'||a.connected?'codeState':'expired';if(a.hasSession)return a.connected?'authenticating':'stopped';if(a.stored)return'stored';return'idle';}
function render(){if(!state)return;renderCalls();renderMedia();renderNasimCalls();renderEitaaCalls();renderRubikaCalls();$('unlockForm').hidden=state.vault.unlocked;$('lock').disabled=!state.vault.unlocked;$('vaultStatus').textContent=t(state.vault.unlocked?'vaultOpen':state.vault.exists?'vaultLocked':'vaultNew');
 for(const a of Object.values(state.providerAccounts||{igap:state.accounts}).flat()){const card=document.querySelector('.account[data-provider="'+a.provider+'"][data-slot="'+a.slot+'"]');if(!card)continue;const signature=a.provider==='rubika'&&!a.busy&&['device_required','registration_uncertain'].includes(a.stage)?'rubika_'+a.stage:a.provider==='nasim'&&!a.busy&&a.stage==='authenticating'?'nasim_authenticating':statusOf(a),previous=card.dataset.status;card.dataset.status=signature;card.dataset.signed=String(a.signedIn);card.querySelector('[data-state-text]').textContent=t(signature)+(a.provider==='nasim'&&a.signedIn&&a.events?.phase==='connected'?' · '+t('eventsConnected'):'');if(previous&&previous!==signature){card.classList.remove('changed');void card.offsetWidth;card.classList.add('changed');}card.querySelector('[data-meta]').textContent=[a.maskedPhone,a.userId?'ID '+a.userId:''].filter(Boolean).join(' · ');
  const loginVisible=!a.hasSession&&!a.stored&&!['password','profile_required','authenticating','restoring'].includes(a.stage);card.querySelector('[data-login]').hidden=!loginVisible;card.querySelector('[data-code-form]').hidden=a.stage!=='code'||a.hasSession;card.querySelector('[data-password-form]').hidden=a.stage!=='password';card.querySelector('[data-profile-form]').hidden=a.stage!=='profile_required';
  for(const element of card.querySelectorAll('button,input,select'))element.disabled=a.busy||!state.vault.unlocked;
  card.querySelector('[data-code-form] button').disabled||=a.provider==='igap'&&!a.connected;card.querySelector('[data-password-form] button').disabled||=a.provider==='igap'&&!a.connected;
  const send=card.querySelector('[data-login] button[type=submit]');send.disabled||=a.retryAfter>0;send.textContent=a.retryAfter?t('send')+' · '+a.retryAfter+' '+t('seconds'):t('send');
  const resume=card.querySelector('[data-action=resume]');resume.hidden=(!a.hasSession&&!a.stored)||a.signedIn;resume.textContent=t(a.hasSession?'resume':'restore');const stop=card.querySelector('[data-action=stop]');stop.hidden=!(a.connected||a.provider==='eitaa'&&['requesting','code','password','restoring'].includes(a.stage));if(a.provider==='eitaa')stop.disabled=!state.vault.unlocked;card.querySelector('[data-action=logout]').hidden=!a.hasSession;card.querySelector('[data-action=forget]').hidden=!a.stored&&!a.hasSession&&a.stage==='idle';
  card.querySelector('[data-error]').textContent=a.error?errorText(a.error):a.provider==='nasim'&&a.events?.reason?t(a.events.reason):'';
  const events=card.querySelector('[data-events-toggle]');if(events){const phase=a.events?.phase||'idle';events.hidden=!a.signedIn;events.disabled=!state.vault.unlocked||!a.signedIn||a.busy&&phase!=='connecting';events.textContent=t(phase==='connected'?'eventsDisconnect':phase==='connecting'?'eventsCancel':'eventsConnect');}card.querySelector('[data-hint]').textContent=a.hint||'';const register=card.querySelector('[data-action=register]');if(register)register.hidden=!(a.hasSession&&a.stage==='device_required');const refresh=card.querySelector('[data-action=refresh]');if(refresh)refresh.hidden=!(a.hasSession&&['refresh_required','expired'].includes(a.stage));const delivery=card.querySelector('[data-rubika-delivery]');if(delivery){delivery.textContent=a.stage==='code'&&a.delivery?t((a.provider==='eitaa'?'eitaa_delivery_':'rubika_delivery_')+a.delivery):'';card.querySelector('[data-meta]').title=[a.deviceModel,a.systemVersion,a.provider==='eitaa'&&!a.deviceMetadataSent?t('eitaa_metadata_unsent'):''].filter(Boolean).join(' · ');}
 }
}
function renderMedia(){
 const media=state?.media;$('mediaPanel').hidden=!media?.available;if(!media?.available)return;
 $('mediaStatus').textContent=t('media_'+media.phase)+(media.reason?' · '+t(media.reason):'');
 const ready=state.accounts.length===2&&state.accounts.every(a=>a.signedIn&&a.call?.phase==='joined'&&a.call.credentialReady);
 $('mediaStart').disabled=!ready||media.busy||['starting','running','preparing'].includes(media.phase);$('mediaStop').disabled=!media.busy&&!['starting','running','preparing'].includes(media.phase);
 for(const input of [$('mediaClient'),$('mediaPort')])input.disabled=media.busy||['starting','running','preparing'].includes(media.phase);
 const rows=(media.bridges||[]).map(b=>{const row=document.createElement('div');row.textContent=t('account')+' '+b.slot+' · '+(b.role==='client'?t('mediaClient'):lang==='fa'?'سرور':'Server')+' · '+(b.peerAuthenticated?(lang==='fa'?'هویت تأیید شد':'Authenticated'):(lang==='fa'?'در انتظار هویت':'Awaiting authentication'))+(b.socksAddress?' · '+b.socksAddress:'')+(Number.isFinite(b.receivedBytes)?' · ↓ '+b.receivedBytes.toLocaleString(lang)+' B · ↑ '+b.sentBytes.toLocaleString(lang)+' B':'')+(b.quic?' · RTT '+Math.round(b.quic.rttMs)+' ms · '+(lang==='fa'?'بستهٔ ازدست‌رفته ':'Lost packets ')+b.quic.lostPackets:'');return row;});$('mediaMetrics').replaceChildren(...rows);
}
let eitaaRequests=0;
async function eitaaAction(action,body={}){
 eitaaRequests++;render();try{await api('eitaa/media/'+action,body);notice('');}catch(e){notice(errorText(e),true);}finally{eitaaRequests--;await poll();render();}
}
function renderEitaaCalls(){
 const pair=state?.eitaaMedia,accounts=state?.providerAccounts?.eitaa||[],calls=pair?.accounts||[],both=accounts.length===2&&accounts.every(a=>a.signedIn);
 $('eitaaCallPanel').hidden=!both&&!calls.some(c=>!['idle','ended'].includes(c.phase));
 const busy=!!pair?.busy||eitaaRequests>0;
 $('eitaaPrepare').disabled=!state?.vault.unlocked||!pair?.available||!both||!pair.canPrepare||busy;
 $('eitaaReset').disabled=!state?.vault.unlocked||!pair?.available||pair.phase==='idle'&&!busy;
 for(const field of [$('eitaaClient'),$('eitaaPort')])field.disabled=!pair?.canPrepare||busy;
 const phase=calls.find(c=>['failed','ringing','dialing','waiting','accepting','confirming','negotiating'].includes(c.phase))?.phase||pair?.phase||'idle';
 $('eitaaCallStatus').textContent=!pair?.available?t('nc_noHelper'):t('ec_'+phase)+(pair.reason?' · '+t(pair.reason):'');
 for(const call of calls){
  const row=document.querySelector('[data-eitaa-call-slot="'+call.slot+'"]');if(!row)continue;
  row.querySelector('[data-eitaa-label]').textContent=t('account')+' '+call.slot+' · '+t(call.slot===pair.clientSlot?'nc_client':'nc_server');
  const status=row.querySelector('[data-eitaa-state]'),old=status.dataset.phase;status.dataset.phase=call.phase;status.textContent=t('ec_'+call.phase);
  if(old&&old!==call.phase){row.classList.remove('changed');void row.offsetWidth;row.classList.add('changed');}
  const media=call.media,values=[],metric=(label,value)=>{const box=document.createElement('span'),name=document.createElement('span'),number=document.createElement('b');name.textContent=label;number.dir='ltr';number.textContent=value;box.append(name,number);values.push(box);};
  const bytes=value=>{let unit=0;while(value>=1024&&unit<3){value/=1024;unit++;}return new Intl.NumberFormat(lang,{maximumFractionDigits:1}).format(value)+' '+['B','KiB','MiB','GiB'][unit];};
  if(media?.socksAddress)metric('SOCKS5',media.socksAddress);
  if(media?.mediaConnected){metric('↓ '+t('nc_download'),bytes(media.receivedBytes));metric('↑ '+t('nc_upload'),bytes(media.sentBytes));}
  if(media?.quic){metric(t('nc_rtt'),new Intl.NumberFormat(lang,{maximumFractionDigits:0}).format(media.quic.rttMs)+' ms');metric(t('nc_loss'),media.quic.lostPackets.toLocaleString(lang)+(media.quic.sentPackets?' · '+new Intl.NumberFormat(lang,{maximumFractionDigits:2}).format(media.quic.lostPackets/media.quic.sentPackets*100)+'%':''));}
  row.querySelector('[data-eitaa-metrics]').replaceChildren(...values);row.querySelector('[data-eitaa-error]').textContent=call.reason?t(call.reason):'';
  for(const button of row.querySelectorAll('[data-eitaa-action]')){const action=button.dataset.eitaaAction;button.hidden=action==='dial'?call.phase!=='ready':action==='accept'?call.phase!=='ringing':['idle','ended','ready','failed','stopped'].includes(call.phase);button.disabled=!both||!state.vault.unlocked||busy||call.busy;if(action==='end')button.disabled=!state.vault.unlocked;}
 }
}
