 row.innerHTML='<strong data-eitaa-label></strong><span data-eitaa-state role="status" aria-live="polite"></span><div class="call-actions"></div><small data-eitaa-metrics class="nasim-metrics"></small><small data-eitaa-error class="nasim-error"></small>';
