  const bytes=value=>{let unit=0;while(value>=1024&&unit<3){value/=1024;unit++;}return new Intl.NumberFormat(lang,{maximumFractionDigits:1}).format(value)+' '+['B','KiB','MiB','GiB'][unit];};
