function renderCalls(){
 const panel=$('callPanel');if(!state||!panel)return;
 const both=state.accounts.length===2&&state.accounts.every(a=>a.signedIn),active=state.accounts.some(a=>a.call&&!['idle','ended'].includes(a.call.phase));panel.hidden=!both&&!active;
 for(const a of state.accounts){const row=document.querySelector('[data-call-slot="'+a.slot+'"]');if(!row)continue;const call=a.call||{phase:'idle'};row.querySelector('[data-call-label]').textContent=t('account')+' '+a.slot;row.querySelector('[data-call-state]').textContent=t('call_'+call.phase);row.querySelector('[data-call-state]').dataset.phase=call.phase;row.querySelector('[data-call-error]').textContent=call.error?errorText(call.error):'';
  for(const button of row.querySelectorAll('[data-call-action]')){const action=button.dataset.callAction;button.disabled=!!call.busy||!a.signedIn;button.hidden=action==='dial'?!['idle','ended'].includes(call.phase):action==='ring'?call.phase!=='incoming'||call.ringing:action==='join'?!['incoming','outgoing'].includes(call.phase):action==='leave'?!call.roomId||['idle','ended'].includes(call.phase):call.phase!=='uncertain';if(action==='dial')button.disabled||=!both;}
 }
}
